def safe_ratio(numerator, denominator):
    if denominator == 0:
        return 0
    return numerator / denominator

def median(values):
    ordered = sorted(values)
    if not ordered:
        return None
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2
